    cin.tie(nullptr);
    int a, b;
    cin >> a >> b;
    if (a > b) swap(a, b);
    if (a == 1) {
        int result = 6 * (b / 6) + 2 * max(0, (b % 6) - 3);
        cout << result << "\n";
    } else if (a == 2) {
        if (b == 2) {
            cout << 0 << "\n";
        } else if (b == 1 || b == 3 || b == 7) {
            cout << a * b - 2 << "\n";
        } else {
            cout << a * b << "\n";
        }
    } else {
        cout << ((a * b) / 2) * 2 << "\n";
    }
    return 0;
}
